            await tx.insert(TransactionsTable)
              .values({
                ...transaction,
                status: "pending", // Always set new transactions to pending
                createdAt: new Date(),
                updatedAt: new Date(),
                });
          }
        )
    }, "FAILED_TO_SAVE_TRANSACTION");
  }

  async update(transaction: ITransactionDBDTO): Promise<ITransactionDBDTO> {
