        orderBy: {
          createdAt: "desc"
        },
        offset: 0,
        limit: 10,
        where: {
          userId: {
            eq: userId
          },
          status: {
            eq: "success"
          },
          AND: [
            ...whereClauses
          ]
        }
      });

      return transactions ?? [];
    }, "FAILED_TO_GET_SUCCESSFUL_TRANSACTIONS");
  }
