import { users } from "../../database/schema/user.repository";
import { CacheFactory, type ICacheStore } from "@/lib/cache";

class UserStore implements IUserStore {
  private cache: ICacheStore;
  private db: typeof defaultDb;

  constructor(cacheStore?: ICacheStore, dbInstance?: typeof defaultDb) {
    this.cache = cacheStore ?? CacheFactory.create();
    this.db = dbInstance ?? defaultDb;
  }

  private getUserByIdCacheKey(id: TUserId): string {
    return `user-by-id:${id}`;
  }

  private getUserByEmailCacheKey(email: string): string {
    return `user-by-email:${email}`;
  }

  async createUser(data: IUserDBDTO): Promise<IUserDBDTO> {
    const createdUser = await tryCatch({
      ctx: async () => {
        const [result] = await this.db
          .insert(users)
          .values({
            id: data.id,
            email: data.email,
            name: data.name,
            emailVerified: data.emailVerified,
            image: data.image,
          })
          .returning();

        if (!result) {
          throw new Error("Failed to create user");
        }
        return result as IUserDBDTO;
      }
    });

    await this.cache.del(this.getUserByEmailCacheKey(createdUser.email));
    await this.cache.del(this.getUserByIdCacheKey(createdUser.id));
    return createdUser;
  };

  getUserByEmail(email: string): Promise<IUserDBDTO | null> {
    return this.cache.getOrSet(this.getUserByEmailCacheKey(email), () => {
        return tryCatch({
            ctx: async () => {
              const [user] = await this.db.select().from(users).where(eq(users.email, email));
              if (!user) return null;
              return user as IUserDBDTO;
            }
          });
    }, 3600);
  };

  getUserById(id: TUserId): Promise<IUserDBDTO | null> {
    return this.cache.getOrSet(this.getUserByIdCacheKey(id), () => {
        return tryCatch({
            ctx: async () => {
              const [user] = await this.db.select().from(users).where(eq(users.id, id));
              if (!user) return null;
              return user as IUserDBDTO;
            }
          });
    }, 3600);
  };

  async deleteUser(id: TUserId): Promise<void> {
    const user = await this.getUserById(id);
    await tryCatch({
      ctx: async () => {
        await this.db.delete(users).where(eq(users.id, id));
      }
    });
    if (user) {
        await this.cache.del(this.getUserByIdCacheKey(id));
        await this.cache.del(this.getUserByEmailCacheKey(user.email));
    }
  };

  async updateUser(data: IUserDBDTO): Promise<IUserDBDTO> {
    const updatedUser = await tryCatch({
      ctx: async () => {
        const [result] = await this.db
          .update(users)
          .set({
            email: data.email,
            name: data.name,
            emailVerified: data.emailVerified,
            image: data.image,
            updatedAt: data.updatedAt,
          })
          .where(eq(users.id, data.id)).returning();

        if (!result) {
          return data;
        }
        return result as IUserDBDTO;
      }
    });

    await this.cache.del(this.getUserByIdCacheKey(updatedUser.id));
    await this.cache.del(this.getUserByEmailCacheKey(updatedUser.email));

    return updatedUser;
  };
};

export const UserRepository = new UserStore();

import { describe, it, expect, beforeEach, vi, afterEach } from "vitest";
import type { IUserDBDTO } from "./user-repo.interface";
import type { TUserId } from "../../../types";
import { UserRepository } from "./user.repo";

vi.mock("../../../lib/cache", () => ({
    CacheFactory: {
        create: vi.fn(() => ({
            get: vi.fn(),
            set: vi.fn(),
            del: vi.fn(),
            getOrSet: vi.fn(),
        })),
    },
}));

vi.mock("../../database/client", () => ({
    db: {
        insert: vi.fn(),
        select: vi.fn(),
        update: vi.fn(),
        delete: vi.fn(),
    }
}));

vi.mock("drizzle-orm", async (importOriginal) => {
  const actual = await importOriginal<any>();
  return {
    ...actual,
    eq: vi.fn(),
  };
});

describe("UserStore (Repository)", () => {
    let mockDb: {
      insert: ReturnType<typeof vi.fn>;
      select: ReturnType<typeof vi.fn>;
      update: ReturnType<typeof vi.fn>;
      delete: ReturnType<typeof vi.fn>;
    };
    let mockCache: {
      get: ReturnType<typeof vi.fn>;
      set: ReturnType<typeof vi.fn>;
      del: ReturnType<typeof vi.fn>;
      getOrSet: ReturnType<typeof vi.fn>;
    };

  const createMockUser = (overrides?: Partial<IUserDBDTO>): IUserDBDTO => ({
    id: `user_${Math.random()}` as TUserId,
    email: "test@example.com",
    name: "Test User",
    createdAt: new Date(),
    updatedAt: null,
    emailVerified: false,
    image: null,
    ...overrides,
  });

  beforeEach(() => {
    vi.clearAllMocks();
    const { db } = require("../../database/client");
    mockDb = db;
    const cacheModule = require("../../../lib/cache");
    mockCache = cacheModule.CacheFactory.create();
    (UserRepository as any).cache = mockCache;
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  describe("createUser", () => {
    it("should invalidate caches on user creation", async () => {
        const userData = createMockUser();
        (mockDb.insert as any).mockReturnValue({
            values: () => ({ returning: () => [userData] }),
        });
        await UserRepository.createUser(userData);
        expect(mockCache.del).toHaveBeenCalledWith(`user-by-email:${userData.email}`);
        expect(mockCache.del).toHaveBeenCalledWith(`user-by-id:${userData.id}`);
    });
  });

  describe("getUserByEmail", () => {
    it("should fetch from DB and set to cache on cache miss", async () => {
        const userData = createMockUser();
        (mockCache.getOrSet as any).mockImplementation(async (key: any, fn: any) => fn());
        (mockDb.select as any).mockReturnValue({
            from: () => ({ where: () => [userData] }),
        });

        const result = await UserRepository.getUserByEmail(userData.email);

        expect(result).toEqual(userData);
        expect(mockCache.getOrSet).toHaveBeenCalledWith(`user-by-email:${userData.email}`, expect.any(Function), 3600);
        expect(mockDb.select).toHaveBeenCalled();
    });
  });

  describe("getUserById", () => {
    it("should fetch from DB and set to cache on cache miss", async () => {
        const userData = createMockUser();
        (mockCache.getOrSet as any).mockImplementation(async (key: any, fn: any) => fn());
        (mockDb.select as any).mockReturnValue({
            from: () => ({ where: () => [userData] }),
        });

        const result = await UserRepository.getUserById(userData.id);

        expect(result).toEqual(userData);
        expect(mockCache.getOrSet).toHaveBeenCalledWith(`user-by-id:${userData.id}`, expect.any(Function), 3600);
        expect(mockDb.select).toHaveBeenCalled();
    });
  });

  describe("deleteUser", () => {
    it("should invalidate caches on user deletion", async () => {
        const userData = createMockUser();
        (mockCache.getOrSet as any).mockResolvedValue(userData);
        (mockDb.delete as any).mockReturnValue({
            where: () => Promise.resolve(),
        });

        await UserRepository.deleteUser(userData.id);

        expect(mockCache.del).toHaveBeenCalledWith(`user-by-id:${userData.id}`);
        expect(mockCache.del).toHaveBeenCalledWith(`user-by-email:${userData.email}`);
    });
  });

  describe("updateUser", () => {
    it("should invalidate caches on user update", async () => {
        const userData = createMockUser();
        (mockDb.update as any).mockReturnValue({
            set: () => ({ where: () => ({ returning: () => [userData] }) }),
        });

        await UserRepository.updateUser(userData);

        expect(mockCache.del).toHaveBeenCalledWith(`user-by-id:${userData.id}`);
        expect(mockCache.del).toHaveBeenCalledWith(`user-by-email:${userData.email}`);
    });
  });
});

